package com.householdfinance.finance.domain;import java.time.*;import java.util.*;public final class FinancialAccount{private final AccountId id;private final HouseholdId householdId;private final String name;private final AccountType type;private final Money currency;private Money balance;private boolean active=true;private FinancialAccount(AccountId i,HouseholdId h,String n,AccountType t,Money c,Money b){id=i;householdId=h;name=n;type=t;currency=c;balance=b;}public static FinancialAccount open(HouseholdId h,String n,AccountType t,Money opening,Instant ignored){if(opening==null)throw new DomainException("Opening balance required");return new FinancialAccount(AccountId.newId(),h,n,t,Money.zero(opening.currency()),opening);}public static FinancialAccount rehydrate(UUID id,HouseholdId h,String n,AccountType t,Money currency,Money balance,boolean active){var account=new FinancialAccount(new AccountId(id),h,n,t,currency,balance);account.active=active;return account;}private void valid(Money a){if(!active||!a.isPositive()||!currency.currency().equals(a.currency()))throw new DomainException("Invalid account amount");}public void credit(Money a,Instant i){valid(a);balance=balance.add(a);}public void debit(Money a,Instant i){valid(a);if(balance.compareTo(a)<0)throw new DomainException("Insufficient account balance");balance=balance.subtract(a);}public AccountId id(){return id;}public HouseholdId householdId(){return householdId;}public String name(){return name;}public AccountType type(){return type;}public Money currency(){return currency;}public Money balance(){return balance;}public boolean active(){return active;}}
